from scipy.optimize import least_squares as ls
def F(kind,p,which):
    z={'t':t,'x':x,'v':v}[which]
    if kind=='pow': return z**p
    if kind=='exp': return np.exp(-p*z)
    if kind=='cos': return np.cos(p*z)
    if kind=='sin': return np.sin(p*z)
    if kind=='lin': return z
    if kind=='one': return np.ones_like(t)
# term spec: list of (kind,var) factors; params per factor
specs=[]
tf=[('pow','t'),('exp','t'),('cos','t'),('sin','t'),('lin','t')]
xf=[('pow','x'),('exp','x'),('lin','x')]
vf=[('pow','v'),('exp','v'),('lin','v')]
terms=[]
for a in tf:
    for b in xf+vf: terms.append((a,b))
for a in xf+vf: terms.append((a,))
for a in tf: terms.append((a,))
def termcols(spec,p):
    out=np.ones_like(t)
    k=0
    for f in spec:
        kind,var=f
        if kind=='lin': val=F('lin',None,var)
        else: val=F(kind,p[k],var); k+=1
        out=out*val
    return out, k
def nparam(spec): return sum(0 if f[0]=='lin' else 1 for f in spec)
def run(s1,s2,starts=5):
    rng=np.random.default_rng(1)
    npp=1+nparam(s1)+nparam(s2)
    best=None
    for _ in range(starts):
        th0=rng.uniform(0.3,2,npp); th0[0]=rng.uniform(0.4,0.6)
        def r(th):
            c0=np.sin(th[0]*t)*np.sqrt(v)
            i=1
            cols=[c0]
            for sp in (s1,s2):
                n=nparam(sp)
                col,_=termcols(sp,th[i:i+n]); i+=n
                cols.append(col)
            A=np.column_stack(cols)
            c=np.linalg.lstsq(A,y,rcond=None)[0]
            return y-A@c
        try:
            s=ls(r,th0,max_nfev=200)
            n=np.mean(s.fun**2)/np.var(y)
            if best is None or n<best[0]: best=(n,s.x.round(4))
        except Exception: pass
    return best
